const loader=new TextureLoader();
let indexPromise:Promise<MaterialIndex>|null=null;
const textureCache=new Map<string,Promise<Texture>>();
function getMaterialIndex():Promise<MaterialIndex>{
  if(!indexPromise) indexPromise=fetch("/viralio-3d/materials/index.json")
    .then(async response=>{
      if(!response.ok)throw Error("Falta índice PBR "+response.status);
      return await response.json() as MaterialIndex;
    }).catch(e=>{indexPromise=null;throw e;});
  return indexPromise;
}
function texture(path:string):Promise<Texture>{
  if(!textureCache.has(path))textureCache.set(path,loader.loadAsync(path).catch(e=>{textureCache.delete(path);throw e;}));
  return textureCache.get(path)!;
}

/** Texturas repetibles; cada material obtiene clones para que pueda variar UV sin afectar otras salas. */
export async function loadViralioPBR(id:string,repeatX=1,repeatY=1):Promise<MeshStandardMaterial>{
  const lib=await getMaterialIndex();
  const entry=lib.materials.find(m=>m.id===id);
  if(!entry)throw Error("Material PBR inexistente: "+id);
  const [base,normal,arm]=await Promise.all([
    texture(entry.maps.color.path),texture(entry.maps.normal.path),texture(entry.maps.arm.path)
  ]);
  const maps=[base.clone(),normal.clone(),arm.clone()];
  for(const map of maps){
    map.wrapS=RepeatWrapping;map.wrapT=RepeatWrapping;
    map.repeat.set(repeatX,repeatY);map.needsUpdate=true;
  }
  maps[0].colorSpace=SRGBColorSpace;
  return new MeshStandardMaterial({
    map:maps[0],normalMap:maps[1],aoMap:maps[2],
    roughnessMap:maps[2],metalnessMap:maps[2],
    roughness:1,metalness:0,side:DoubleSide
  });
}
async function addProp(root:Group,prop:Prop){
  const {scene}=await loadViralio3DAsset(prop.id);
  const bounds=new Box3().setFromObject(scene);
  const center=new Vector3();bounds.getCenter(center);
  scene.position.set(prop.x-center.x,-bounds.min.y,prop.z-center.z);
  scene.rotation.y=prop.rotate||0;
  scene.userData.viralioAssetId=prop.id;
  root.add(scene);
}
function wall(root:Group,x:number,y:number,z:number,w:number,h:number,d:number,material:MeshStandardMaterial){
  const mesh=new Mesh(new BoxGeometry(w,h,d),material);
  mesh.position.set(x,y,z);
  mesh.receiveShadow=true;
  mesh.userData.wall=true;
  root.add(mesh);
}
export type ViralioRoom = { group:Group; style:RoomStyle; loadedAssets:string[]; failedAssets:string[] };
/**
 * Creates a 7x7m room by default, with a 1.4m entrance gap facing +Z.
 * The entrance is intentionally NOT blocked by a static prop.
 * Keep real collision and puzzle logic inside each game.
 */
export async function createViralioRoom(
  style:RoomStyle,opts:{width?:number;depth?:number;height?:number;props?:boolean}={}
):Promise<ViralioRoom>{
  const c=styles[style];
  const width=Math.max(5,Math.min(18,opts.width||7));
  const depth=Math.max(5,Math.min(18,opts.depth||7));
  const height=Math.max(2.4,Math.min(5,opts.height||3.3));
  const [walls,floor,ceiling]=await Promise.all([
    loadViralioPBR(c.walls,width/2,height/2),
    loadViralioPBR(c.floor,width/2,depth/2),
    loadViralioPBR(c.ceiling,width/2,depth/2)
  ]);
  const room=new Group();
  room.name="Viralio-"+style;
  wall(room,0,-.12,0,width,.24,depth,floor);
  wall(room,0,height+.1,0,width,.2,depth,ceiling);
  wall(room,0,height/2,-depth/2,width,height,.18,walls);
  wall(room,-width/2,height/2,0,.18,height,depth,walls);
  wall(room,width/2,height/2,0,.18,height,depth,walls);
  const gap=1.5;
  const side=(width-gap)/2;
  wall(room,-(gap+side)/2,height/2,depth/2,side,height,.18,walls);
  wall(room,(gap+side)/2,height/2,depth/2,side,height,.18,walls);
  wall(room,0,height-.35,depth/2,gap,.7,.18,walls);
  const lamp=new PointLight(c.warm,18,13,1.8);lamp.position.set(0,height-.35,0);room.add(lamp);
  const loadedAssets:string[]=[],failedAssets:string[]=[];
  if(opts.props!==false){
    await Promise.all(c.fixtures.map(async p=>{
      try{await addProp(room,p);loadedAssets.push(p.id);}
      catch(error){failedAssets.push(p.id);console.warn("Viralio prop unavailable",p.id,error);}
    }));
  }
  return {group:room,style,loadedAssets,failedAssets};
}
export const VIRALIO_ROOM_STYLES=Object.keys(styles) as RoomStyle[];
